import React, { useEffect } from 'react';

export const VLibras: React.FC = () => {
  useEffect(() => {
    // Cria o container do VLibras se não existir
    if (!document.querySelector('div[vw]')) {
      const vLibrasDiv = document.createElement('div');
      vLibrasDiv.setAttribute('vw', '');
      vLibrasDiv.classList.add('enabled');
      
      const accessButton = document.createElement('div');
      accessButton.setAttribute('vw-access-button', '');
      accessButton.classList.add('active');
      
      const pluginWrapper = document.createElement('div');
      pluginWrapper.setAttribute('vw-plugin-wrapper', '');
      
      const topWrapper = document.createElement('div');
      topWrapper.classList.add('vw-plugin-top-wrapper');
      
      pluginWrapper.appendChild(topWrapper);
      vLibrasDiv.appendChild(accessButton);
      vLibrasDiv.appendChild(pluginWrapper);
      document.body.appendChild(vLibrasDiv);
    }

    // Carrega o script do VLibras
    const script = document.createElement('script');
    script.src = 'https://vlibras.gov.br/app/vlibras-plugin.js';
    script.async = true;
    
    script.onload = () => {
      // @ts-ignore
      new window.VLibras.Widget('https://vlibras.gov.br/app');
    };

    document.head.appendChild(script);

    return () => {
      // Limpa quando o componente for desmontado
      const vLibrasDiv = document.querySelector('div[vw]');
      if (vLibrasDiv) {
        document.body.removeChild(vLibrasDiv);
      }
      const scriptElement = document.querySelector('script[src="https://vlibras.gov.br/app/vlibras-plugin.js"]');
      if (scriptElement) {
        document.head.removeChild(scriptElement);
      }
    };
  }, []);

  // Não precisa retornar nada no JSX pois estamos manipulando o DOM diretamente
  return null;
};
